window.ScripturaLexicons.BDAG_PART_0177 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-01\" data-source=\"BDAG\" data-search=\"ἱππικός, ή, όν adjetivo da cavalaria; relativo a cavaleiros BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱππικός, ή, όν</td><td>adjetivo</td><td>da cavalaria; relativo a cavaleiros</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-02\" data-source=\"BDAG\" data-search=\"ἵππος, ου, ὁ substantivo masculino cavalo; corcel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἵππος, ου, ὁ</td><td>substantivo masculino</td><td>cavalo; corcel</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-03\" data-source=\"BDAG\" data-search=\"ἶρις, ιδος, ἡ substantivo feminino arco-íris; halo luminoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἶρις, ιδος, ἡ</td><td>substantivo feminino</td><td>arco-íris; halo luminoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-04\" data-source=\"BDAG\" data-search=\"Ἰσαάκ, ὁ nome próprio masculino; indeclinável Isaque; filho de Abraão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰσαάκ, ὁ</td><td>nome próprio masculino; indeclinável</td><td>Isaque; filho de Abraão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-05\" data-source=\"BDAG\" data-search=\"ἰσάγγελος, ον adjetivo semelhante aos anjos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσάγγελος, ον</td><td>adjetivo</td><td>semelhante aos anjos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-06\" data-source=\"BDAG\" data-search=\"ἴσθι forma verbal remissiva ver εἰμί BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἴσθι</td><td>forma verbal remissiva</td><td>ver εἰμί</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-07\" data-source=\"BDAG\" data-search=\"Ἰσκαριώθ nome próprio masculino; epíteto Iscariotes; epíteto de Judas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰσκαριώθ</td><td>nome próprio masculino; epíteto</td><td>Iscariotes; epíteto de Judas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-08\" data-source=\"BDAG\" data-search=\"Ἰσοκράτης, ους, ὁ nome próprio masculino Isócrates; escriba cristão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰσοκράτης, ους, ὁ</td><td>nome próprio masculino</td><td>Isócrates; escriba cristão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-09\" data-source=\"BDAG\" data-search=\"ἴσος, η, ον adjetivo igual; de igual valor ou qualidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἴσος, η, ον</td><td>adjetivo</td><td>igual; de igual valor ou qualidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-10\" data-source=\"BDAG\" data-search=\"ἰσότης, ητος, ἡ substantivo feminino igualdade; equidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσότης, ητος, ἡ</td><td>substantivo feminino</td><td>igualdade; equidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-11\" data-source=\"BDAG\" data-search=\"ἰσότιμος, ον adjetivo igual em honra; do mesmo valor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσότιμος, ον</td><td>adjetivo</td><td>igual em honra; do mesmo valor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-12\" data-source=\"BDAG\" data-search=\"ἰσόχρονος, ον adjetivo contemporâneo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσόχρονος, ον</td><td>adjetivo</td><td>contemporâneo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-13\" data-source=\"BDAG\" data-search=\"ἰσόψυχος, ον adjetivo da mesma disposição; semelhante de alma BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσόψυχος, ον</td><td>adjetivo</td><td>da mesma disposição; semelhante de alma</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-14\" data-source=\"BDAG\" data-search=\"ἰσοψύχως advérbio de modo semelhante; remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσοψύχως</td><td>advérbio</td><td>de modo semelhante; remissão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-15\" data-source=\"BDAG\" data-search=\"Ἰσραήλ, ὁ nome próprio masculino; indeclinável Israel; Jacó; povo de Israel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰσραήλ, ὁ</td><td>nome próprio masculino; indeclinável</td><td>Israel; Jacó; povo de Israel</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-16\" data-source=\"BDAG\" data-search=\"Ἰσραηλίτης, ου, ὁ substantivo masculino israelita BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰσραηλίτης, ου, ὁ</td><td>substantivo masculino</td><td>israelita</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-17\" data-source=\"BDAG\" data-search=\"Ἰσσαχάρ, ὁ nome próprio masculino; indeclinável Issacar; filho de Jacó BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰσσαχάρ, ὁ</td><td>nome próprio masculino; indeclinável</td><td>Issacar; filho de Jacó</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-18\" data-source=\"BDAG\" data-search=\"ἴστε forma verbal remissiva ver οἶδα BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἴστε</td><td>forma verbal remissiva</td><td>ver οἶδα</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-19\" data-source=\"BDAG\" data-search=\"ἵστημι verbo pôr; estabelecer; estar de pé; permanecer firme BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἵστημι</td><td>verbo</td><td>pôr; estabelecer; estar de pé; permanecer firme</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0177-20\" data-source=\"BDAG\" data-search=\"ἱστίον, ου, τό substantivo neutro vela de embarcação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱστίον, ου, τό</td><td>substantivo neutro</td><td>vela de embarcação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0177-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱππικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver os verbetes anterior e seguinte; Ésquilo e outros ; ins , pap ; 1 Macc 15:38 ; 3 Macc 1:1 ; TestSol 11:6 C; Philo ; Jos. , Bell. 2, 117 ; 308 ) relativo a quem monta cavalos, <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱ</span> . a cavalaria ( Hdt. 7, 87 al. ; SIG 697e, 5 Diocles , referente aos <span class=\"greek\">στρατηγῶν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱππικόν</span> ) <span class=\"greek\">τὰ</span> <span class=\"greek\">στρατεύματα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱ</span> . as tropas da cavalaria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:16</a>. — DELG sob o verbete <span class=\"greek\">ἵππος</span> . M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵππος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver os dois verbetes anteriores; Hom .+) cavalo, corcel <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:3</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:9</a> ; 14:20 ; 18:13 ; 19:18. Cavalos de diversas cores desempenham papel destacado no Apocalipse (ver <span class=\"greek\">πυρρός</span> ): um cavalo branco ( Aeneas Tact . 1488) 6:2 ; 19:11, 14 ; cf. os versículos 19, 21 ; vermelho como fogo 6:4 ; preto no versículo 5 ; pálido, baio, no versículo 8. Gafanhotos semelhantes a cavalos 9:7 ; cavalos com cabeças de leão no versículo 17 ; cf. 19. Ver MMüller, D. apokal. Reiter: ZNW 8, 1907, 290ff; GHoennicke, D. apokal. Reiter: Studierstube 19, 1921, 3ff; AvHarnack, D. apokal. Reiter: Erforschtes u. Erlebtes 1923, 53ff; LKöhler, D. Offenb. d. Joh. 1924, 59–68; Boll 78ff, concordando com ele GBaldensperger, RHPR 4, 1924, 1ff, contra sua posição JFreundorfer, Die Apk. des Ap. Joh. 1929, 67–123; FDornseiff, ZNW 38, ’39, 196f; B. 167f; BHHW III 1438f; Pauly-W . XIX 2, 1430–44; Kraft, Hdb. ’74, 114–18.— DELG . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἶρις, ιδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(também com genitivo <span class=\"greek\">ἴρεω</span> )</p><p class=\"entry-text\">① arco-íris ( Hom . et al. ): ApcPt 3:10 ( Mel. , fgm, 8b 11); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:3</a> ; 10:1.</p><p class=\"entry-text\">② um arco ou círculo de luz, colorido ou não: halo, resplendor ( Aristot ., Meteor. 3, 4; 5; Theophr ., Ostent. 1, 13; Lucian , Dom. 11) <span class=\"greek\">ἶρις</span> <span class=\"greek\">ὅμοιος</span> <span class=\"greek\">ὁράσει</span> <span class=\"greek\">σμαραγδίνῳ</span> um halo que, na aparência, se assemelhava a uma esmeralda; alguns estudiosos propuseram esse significado para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:3</a>, mas a reminiscência de Ezk 1:27f favorece decisivamente o sentido 1 acima.— M-M . DELG . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰσαάκ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino; indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( יִצְחָק ; variante de leitura <span class=\"greek\">Ἰσάκ</span> [ B-D-F § 39, 3 ]) indeclinável ( LXX , TestAbr , Test12Patr , ParJer ; ApcrEzk P 1 verso 11; SibOr 2, 247; Philo ; Just ., Mel. — Josefo e EpArist 48 <span class=\"greek\">Ἴσακος</span>, <span class=\"greek\">ου</span> [ Ant. 1, 227 ]; EpArist 49 <span class=\"greek\">Ἴσαχος</span> ) Isaque, filho de Abraão ( Gen 21:3ff ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:8a</a> ; GJs 1:3. Pai de Jacó, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:8b</a>. Mencionado juntamente com Jacó e Abraão (ver <span class=\"greek\">Ἀβραάμ</span> e <span class=\"greek\">Ἰακώβ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:11</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:28</a> ; B 8:4 ; IPhld 9:1 ; GJs 20:2 (não consta do papiro ). Deus como Deus de Abraão, Isaque e Jacó ( Ex 3:6 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:32</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:26</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:37</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:13</a> ; 7:32 ; B 6:8 . Portador das promessas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:7</a> ( Gen 21:12 ), 10 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:28</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:9</a>, 18 ( Gen 21:12 ), 20. Marido de Rebeca <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:10</a> ; B 13:2 ( Gen 25:21 ), 3. Sacrifício de Isaque ( Gen 22:1ff ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:17</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:21</a> ; 1 Cl 31:3 ; B 7:3 . Na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:2</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:34</a>. —HSchoeps, The Sacrifice of Isaac in Paul’s Theology: JBL 65, ’46, 385–92.— M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσάγγελος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">ἴσος</span> e <span class=\"greek\">ἄγγελος</span> ; Iambl . in Stob ., Ecl. I 457, 9 W.; Hierocles 4, 425 <span class=\"greek\">ἀνθρώπους</span> <span class=\"greek\">σέβειν</span> … <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἰσοδαίμονας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἰσαγγέλους</span> . inscrição funerária cristã : Kaibel 542, 7 <span class=\"greek\">ἰσαγ</span>[<span class=\"greek\">γέλου</span> <span class=\"greek\">τύχης</span>] ; cf. Philo , Sacr. Abel. 5 <span class=\"greek\">ἴσος</span> <span class=\"greek\">ἀγγέλοις</span> <span class=\"greek\">γεγονώς</span> ) semelhante aos anjos, dito dos glorificados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:36</a> (citado em Just ., D . 81, 4).— M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴσθι</h1><div class=\"entry-meta\"><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">ver <span class=\"greek\">εἰμί</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰσκαριώθ</h1><div class=\"entry-meta\"><span>nome próprio masculino; epíteto</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">indeclinável ( <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:19</a> ; 14:10 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:16</a> ; 22:47 D ), e <span class=\"greek\">Ἰσκαριώτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (assim em todas as demais passagens e sempre no texto recebido ; o códice D apresenta predominantemente <span class=\"greek\">Σκαριώθ</span> , <span class=\"greek\">Σκαριώτης</span> , ver verbete Sobre o sufixo YArbeitmann, JBL 99, ’80, 122–24) Iscariotes, sobrenome de Judas, o delator de Jesus, e também de seu pai (ver <span class=\"greek\">Ἰούδας</span> 6). O significado da palavra é obscuro; ver Wlh., comentário a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:19</a> ; Dalman , Jesus 26 ( tradução inglesa 51f). Normalmente, entende-se que remete ao lugar de sua origem, Queriote (no sul da Judeia; Buhl 182) אִישׁ קְרִיּוֹת (em consonância com isso, encontra-se a variante de leitura <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Καρυώτου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.71\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:71</a> ; 12:4 D ; 13:2 D , 26 D ; 14:22 D ). Outra interpretação relaciona o termo com <span class=\"greek\">σικάριος</span> (ver verbete), «assassino, bandido» (entre outros FSchulthess, D. Problem der Sprache Jesu 1917, 41; 55, ZNW 21, 1922, 250ff). Ver também CTorrey, HTR 36, ’43, 51–62 («indivíduo falso»). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:4</a> ; 26:14 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:43</a> variante de leitura ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:3</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.71\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:71</a> ; 12:4 ; 13:2, 26 ; 14:22 ; GEb 34, 61.—HIngholt, Iscariot: JPedersen Festschr. ’53; BGärtner, D. rätselhafte Termini Nazaräer u. Iskarioth ’57, 37–68; OCullmann, RHPR 42, ’62, 133–40; KLüthi, J. Isk. in d. Geschichte der Auslegung (da Reforma ao presente) ’55.— M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰσοκράτης, ους, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(literatura, inscrições e papiros) Isócrates, escriba cristão EpilMosq 5ab.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴσος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver os três verbetes seguintes; Hom .+) relativo a equivalência em número, tamanho ou qualidade: igual <span class=\"greek\">τράγοι</span> B 7:10 . <span class=\"greek\">τὸ</span> <span class=\"greek\">μῆκος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλάτος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὕψος</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">ἴσα</span> <span class=\"greek\">ἐστίν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:16</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἴ</span>. <span class=\"greek\">δωρεά</span> o mesmo dom <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:17</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀγάπην</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">ἴ</span>. <span class=\"greek\">παρέχειν</span> demonstrar o mesmo grau de amor 1 Cl 21:7 . Referindo-se a testemunhos concordantes prestados por testemunhas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:56</a>, 59. <span class=\"greek\">ἴσον</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span> tratar alguém de modo igual a outra pessoa ( Polyb . 2, 38, 8; 2 Macc 9:15 <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἴσους</span> <span class=\"greek\">Ἀθηναίοις</span> <span class=\"greek\">ποιήσειν</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:12</a>. <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> fazer-se igual a Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:18</a> ( cf. Philo , Leg. All. 1, 49 <span class=\"greek\">ἴσος</span> <span class=\"greek\">θεῷ</span> ).—Empregado substantivamente, <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴσα</span>, uma quantia igual ( PRyl 65, 7 [I b.c. ] <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">βασιλικὸν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴσα</span> ) <span class=\"greek\">ἀπολαβεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴ</span> . receber uma quantia igual em retribuição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:34</a>. —O neutro plural <span class=\"greek\">ἴσα</span> (como o neutro singular <span class=\"greek\">ἴσον</span> ; TestAbr A 1 p. 77, 8 [Stone p. 2]) funciona como advérbio ( Hom . et al. ; Diod S 1, 89, 1; Wsd 7:3 ) com dativo ( Demosth . 19, 314; oft. Philostrat . [ Schmid IV 48]; Himerius , Or. 20, 4 W. <span class=\"greek\">ἴσα</span> <span class=\"greek\">ποιηταῖς</span> ; PTebt 278, 33 [I a.d. ]; Job 11:12 ; 30:19 ) <span class=\"greek\">ἴσα</span> <span class=\"greek\">εἶναί</span> <span class=\"greek\">τινι</span> ser igual a alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:6</a> (=PEg 3 86f; <span class=\"greek\">ἴσα</span> <span class=\"greek\">εἶναι</span>, como em Thu . 3, 14, 1; <span class=\"greek\">ἴσα</span> <span class=\"greek\">θεῷ</span>, como em Dionys. Byz. §24 p. 12, 14; §41 p. 17, 12; Himerius , Or. [Ecl.] 3, 20; ver W-S. §28, 3; B-D-F § 434, 1 ; Aeschyl ., Pers. 856 <span class=\"greek\">ἰσόθεος</span> referindo-se a um rei; assim também Philod ., Rhet. II p. 57, 11 Sudh. referindo-se a um filósofo; Nicol. Dam.: 90 Fgm. 130, 97 Caesar <span class=\"greek\">τὸν</span> <span class=\"greek\">ἴσα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θεὸν</span> <span class=\"greek\">τιμώμενον</span> ; 117 Jac. ; Ael. Aristid. 46 p. 319 D .: <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἴσου</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">ἐθαυμάζετο</span> ; TestAbr 12 p. 91, 24f [Stone p. 30]; outras referências SLösch, Deitas Jesu und Antike Apotheose ’33, 124f; para uma crítica da busca vaidosa de honras divinas ver Plut ., Mor. 360c). <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἴσου</span> ( Soph ., Hdt. et al. ; SIG 969, 84; pap ; Tat . 4, 2 <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἴσης</span> <span class=\"greek\">τῷ</span> … <span class=\"greek\">θεῷ</span> ; Ath. , R. 49, 20) igualmente, de modo semelhante Pol 4:2 .— B. 910. Larfeld I 497. LfgrE sob o verbete <span class=\"greek\">ἴσος</span> col. 1227 ( lit. ). Cf. <span class=\"greek\">ὅμοιος</span> Schmidt, Syn. IV 472–87. DELG . M-M . TW . Spicq . Sv .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver o verbete anterior; Eur . et al. ; frequentemente em Fílon ; somente duas vezes na LXX ; EpArist 263 ).</p><p class=\"entry-text\">① condição em que as coisas são mantidas em equilíbrio adequado: igualdade ( Ps.-Phoc . 137) <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἰσότητος</span> por questão de igualdade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:13</a> ; também <span class=\"greek\">ὅπως</span> <span class=\"greek\">γένηται</span> <span class=\"greek\">ἰ</span> . para que haja igualdade no versículo 14.</p><p class=\"entry-text\">② condição de ser justo, equidade, como extensão do sentido 1 ( Menand ., Monost., 259 Mei.; Polyb . 2, 38, 8 <span class=\"greek\">ἰ</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">φιλανθρωπία</span> ; Diod S 5, 71, 2 [=362 J.]; Vett. Val. 332, 34) com <span class=\"greek\">τὸ</span> <span class=\"greek\">δίκαιον</span> ( cf. Diog. L. 7, 126; Philo , Spec. Leg. 4, 231 <span class=\"greek\">ἰσότης</span> <span class=\"greek\">μήτηρ</span> <span class=\"greek\">δικαιοσύνης</span> ) justiça e equidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:1</a>. Sobre o tratamento justo dispensado a escravos ver Pl. Leges 5, 776d–788a; Aristot . Politica 1260b, 6; Seneca, Letter 47.—Sobre o assunto: PvanderHorst, The Sentences of Pseudo-Phocyclides ’78, 205 (referências); RHirzel, Themis, Dike u. Verwandtes 1907; Betz , 2 Cor ( Hermeneia ) 67f.— DELG sob o verbete <span class=\"greek\">ἴσος</span> . M-M . TW . Spicq .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσότιμος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">ἴσος</span> e <span class=\"greek\">τιμή</span> ; Strabo 15, 3, 20; Dio Chrys . 24 [41], 2; Plut . et al. ; OGI 234, 25 [c. 200 b.c. ]; 544, 33 [ adv. ]; PRyl 253; Mitt-Wilck. I/2, 13, 10; Philo ; Jos. , Ant. 12, 119 ; Ath. 22, 2) em geral, «igual em honra/valor», mas também simplesmente igual, semelhante, da mesma espécie ou do mesmo valor ( Aelian , NA 10, 1; Herodian 2, 3, 6; Herm. Wr. 12, 12; Jos. , Ant. 12, 3 , 1 «com privilégios iguais») <span class=\"greek\">ἰσότιμον</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">πίστιν</span> uma fé da mesma espécie que a nossa = uma fé dotada do mesmo privilégio que a nossa ( isto é, os destinatários não se acham em condição inferior à dos apóstolos) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:1</a>. Cf. SJCh 92, 1–3 .— M-M . TW . Spicq .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσόχρονος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(em vários sentidos desde o astrônomo Eudoxo, no século IV a.C. ) contemporâneo SJCh 91, 14 ; 92, 2 .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσόψυχος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">ἴσος</span> e <span class=\"greek\">ψυχή</span> ; Aeschyl ., Agam. 1470; escólio sobre Eur ., Andr. 419; Ps 54:14 ) de alma/mente semelhante; da mesma disposição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:20</a> (AFridrichsen, SymbOsl 18, ’38, 42–49 propõe acrescentar <span class=\"greek\">ὑμῖν</span> : tendo muito em comum convosco. O mesmo pesquisador ConNeot 7, ’42, 3, referindo-se ao advérbio <span class=\"greek\">ἰσοψύχως</span> em AcPl Ha 6, 8; PChristou, JBL 70, ’51, 293–96: «confidente»).— M-M . Sv .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσοψύχως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio de <span class=\"greek\">ἰσόψυχος</span> ; AcPl Ha 6, 8.—Bibliografia: ver <span class=\"greek\">ἰσόψυχος</span> .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰσραήλ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino; indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">indeclinável ( יִשְׂרָאֵל . Sobre a grafia <span class=\"greek\">Ἰστραήλ</span> ver B-D-F 39, 5 ; sobre o significado Just ., D . 125, 1ff; Mel. , P. 82, 603 com nota p. 185 Perler) ( LXX , pseudepígrafos , Philo , Just ., Mel. ; PGM 4, 3034; 3055 al. — Jos. , Ant. 1, 333 <span class=\"greek\">Ἰσράηλος</span> ).</p><p class=\"entry-text\">① o patriarca Jacó, Israel; <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">Ἰ</span> . os descendentes de Israel <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:6a</a>. Também <span class=\"greek\">ἐκ</span> <span class=\"greek\">γένους</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:5</a> ( cf. 1 Esdr 1:30 ; Jdth 6:2 ); <span class=\"greek\">οἶκος</span> <span class=\"greek\">Ἰ</span> . a casa de Israel = todos os descendentes do patriarca ( cf. Jdth 14:5 ; 3 Macc 2:10 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:6</a> ; 15:24 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:36</a> ; 7:42 ( Am 5:25 ); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:10</a> ( Jer 38:33 ); 1 Cl 8:3 ( citação de origem desconhecida ; AcPlCor 2:10). Também <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">Ἰ</span> . ( Mi 5:2 ; Sir 46:10 ; 47:2 e frequentemente ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:9</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:16</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:21</a> ; 7:23, 37 ; 9:15 ; 10:36 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:27b</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:7</a>, 13 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:22</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:14</a> ; 7:4 ; 21:12 ; AcPlCor 2:32 (também no sentido de 2). Por outro lado, <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκος</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:8</a> em contraste com <span class=\"greek\">οἶκος</span> <span class=\"greek\">Ἰούδα</span> (segundo Jer 38:31 ) designa o povo do Reino do Norte. Algumas das passagens mencionadas aqui talvez pertençam a</p><p class=\"entry-text\">② o povo/nação de Israel: Israel ( Just ., A I, 53, 4 <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">Ἰουδαικὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Σαμαρειτικὸν</span> <span class=\"greek\">φῦλον</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">κέκληνται</span> ‘os povos judeano e samaritano são chamados Israel’) <span class=\"greek\">τὸν</span> <span class=\"greek\">λαόν</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:6</a> ; <span class=\"greek\">ἄκουε</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:29</a> ( Dt 6:4 ).— <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:54</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:27a</a>, 31 ; 10:19 ; 11:7, 25f ; 1 Cl 29:2 ( Dt 32:9 ); 43:5; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:10</a> ; 9:33 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:34</a> ; 4:25, 27 ; 7:9 ; 1 Cl 43:6 ; B 4:14 ; <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:2</a> ; <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.80\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:80</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:21</a> ; B 5:2 ; <span class=\"greek\">τὶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . PtK 3; <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:42</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:32</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.49\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:49</a> ; 12:13 ; GPt 3:7; 4:11; 1 Cl 4:13 ; <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:6</a> ; <span class=\"greek\">διδάσκαλος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:10</a> ; <span class=\"greek\">πολιτεία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:12</a> ; <span class=\"greek\">πόλεις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:23</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">Ἰ</span> . 15:31 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.68\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:68</a> ( TestSol ); <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:17</a> ; <span class=\"greek\">γῆ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:20f</a> ; <span class=\"greek\">ὁ</span> <span class=\"greek\">λαὸς</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:32</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:10</a> ; 13:24. O plural <span class=\"greek\">λαοὶ</span> <span class=\"greek\">Ἰ</span> . no versículo 27 por causa da citação Ps 2:1 no versículo 25. <span class=\"greek\">πρεσβύτεροι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:8</a> variante de leitura <span class=\"greek\">αἱ</span> <span class=\"greek\">φυλαὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . as tribos de Israel ( CIG IV 9270 [Icônio; provavelmente judeano] <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">φυλῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰσραήλ</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:30</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:4</a> ; 21:12. <span class=\"greek\">τὸ</span> <span class=\"greek\">δωδεκάφυλον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . as doze tribos de Israel 1 Cl 55:6 . <span class=\"greek\">τὸ</span> <span class=\"greek\">δωδεκάσκηπτρον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . 31:4; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐλπὶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:20</a> ; <span class=\"greek\">παράκλησιν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:25</a> ; <span class=\"greek\">λύτρωσιν</span> <span class=\"greek\">Ἰ</span> . versículo 28, variante de leitura ; cf. <span class=\"greek\">λυτροῦσθαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰ</span> . 24:21 ; <span class=\"greek\">ἐρύσατο</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰ</span> . AcPl Ha 8, 10. <span class=\"greek\">ἵνα</span> <span class=\"greek\">φανερωθῇ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:31</a>. <span class=\"greek\">δοῦναι</span> <span class=\"greek\">μετάοιαν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:31</a>. <span class=\"greek\">ἤγαγεν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">σωτῆρα</span> <span class=\"greek\">Ἰησοῦν</span> 13:23. — <span class=\"greek\">Ἰ</span> . é a principal autodesignação do antigo povo de Deus; partindo desse emprego, também se aplica a</p><p class=\"entry-text\">③ cristãos enquanto legitimados a receber o nome Israel: Israel (por exemplo, Just ., D . 123, 7 Trifão pergunta <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">ἐστε</span>; 135, 3 resposta de Justino <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κοιλίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">λατομηθέντες</span> <span class=\"greek\">Ἰσραηλιτικὸν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀληθινόν</span> <span class=\"greek\">ἐσμεν</span> <span class=\"greek\">γένος</span> ; cf. Plut ., Mor. 352c <span class=\"greek\">Ἰσιακός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἀληθῶς</span> de um genuíno adorador de Ísis) em contraste com <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> Israel em sentido físico <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:18</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> o (verdadeiro) Israel de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:16</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">οὗτοι</span> <span class=\"greek\">Ἰ</span> . nem todos os que descendem de Israel (=Jacó), ou que pertencem à nação israelita, são verdadeiramente israelitas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:6</a>. —FMaier, I. in d. Heilsgesch. nach Rö 9–11, 1929.—JJocz, A Theology of Election: Israel and the Church ’58; JMunck, Paul and the Salvation of Mankind (tradução de GClarke) ’59; WTrilling, Das Wahre Israel (Mt) 3 ’64; JvanGoudoever, NovT 8, ’66, 111–23 (Lk); GStrecker, D. Weg d. Gerechtigkeit, ’66, especialmente 99–118.— EDNT . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰσραηλίτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( do hebraico יִשְׂרְאֵלִי ; também a terminação -<span class=\"greek\">είτης</span> [como em Boffo, Iscrizioni , inscrição p. 48 no. 2, 1= SEG XXXII, 809, cf. - <span class=\"greek\">ῖται</span> no. 810]; LXX , Test12Patr ; Josefo, índice; Just .—Como forma feminina : Inschrift 44 da Villa Torlonia, em Roma, edição de HBeyer e HLietzmann 1930; <span class=\"greek\">Ἰσραηλῖτις</span> Mel. , P. 96, 737) israelita <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:47</a> ( cf. Plut ., Mor. 352c <span class=\"greek\">Ἰσιακός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἀληθῶς</span> referente a um genuíno adorador de Ísis); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:4</a> ; 11:1 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:22</a>. Como forma de tratamento <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">Ἰσραηλῖται</span> homens de Israel ( Jos. , Ant. 3, 189 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:22</a> ; 3:12 ; 5:35 ; 13:16 ; 21:28. — M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰσσαχάρ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino; indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(também a terminação -<span class=\"greek\">άχαρ</span> , <span class=\"greek\">Ἰσαχάρ</span> t.r. ; יִשָּׂשכָר ) indeclinável ( LXX ; Test12Patr [ <span class=\"greek\">Ἰσαχάρ</span> ]; Philo .— Jos. , Ant. 1, 308 <span class=\"greek\">Ἰσσαχάρης</span> ; 2, 178 <span class=\"greek\">Ἰσακχάρου</span> ) Issacar, filho do patriarca Jacó ( Gen 30:18 ; Demetr .: 722 Fgm. 1, 4 al. Jac. ), e, por conseguinte, uma tribo israelita Gen 49:14 ; Num 1:26 al. ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:7</a> ( variante de leitura <span class=\"greek\">Ἰσαχάρ</span> ; assim também em Test12Patr e em variantes de Fílon ).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴστε</h1><div class=\"entry-meta\"><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">ver <span class=\"greek\">οἶδα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵστημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( Hom .+, ins , pap [ Mayser 353]; LXX [ Thackeray 247f]; pseudepigr. , Philo , Joseph ., literatura apologética, exceto Ar. ) e também <span class=\"greek\">ἱστάνω</span> (desde o séc. I a.C. SIG 1104, 26 <span class=\"greek\">ἱστανόμενος</span> ; pap [ Mayser , loc. cit ., com <span class=\"greek\">ἀνθιστάνω</span> atestado aqui já no séc. III a.C. ]; Epict . 3, 12, 2; LXX [ Ezk 17:14 ; Thackeray , loc. cit .]; em autores posteriores, conforme Psaltes 236) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:31</a> ; Hs 8, 1, 10 (ver Whittaker sobre 8, 1, 8; ver B-D-F § 93 ; Mlt-H. 202). Futuro <span class=\"greek\">στήσω</span> ; 1º aoristo <span class=\"greek\">ἔστησα</span> ; 2º aoristo <span class=\"greek\">ἔστην</span> , imperativo <span class=\"greek\">στῆθι</span> , infinitivo <span class=\"greek\">στῆναι</span> , particípio <span class=\"greek\">στάς</span> ; perfeito <span class=\"greek\">ἕστηκα</span> («estou em pé»), particípio <span class=\"greek\">ἑστηκώς</span>, <span class=\"greek\">ός</span> e <span class=\"greek\">ἑστώς</span> En 12:3 ; JosAs 7:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:29</a>, - <span class=\"greek\">ῶσα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:9</a> variante de leitura, neutro <span class=\"greek\">ἑστώς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:1</a> variante de leitura (ver B-D-F § 96 ; W-S. §14, 5; Mlt-H. 222) e <span class=\"greek\">ἑστός</span> , infinitivo sempre <span class=\"greek\">ἑστάναι</span> ; mais-que-perfeito <span class=\"greek\">εἱστήκειν</span> («estava em pé») ou <span class=\"greek\">ἱστήκειν</span> GPt 2:3, terceira pessoa do plural <span class=\"greek\">εἱστήκεισαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:46</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:18</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:7</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:11</a> ( W-H. registram a grafia <span class=\"greek\">ἱστ</span> . em todas as ocorrências); <span class=\"greek\">ἑστάκαμεν</span> com significado ativo 1 Macc 11:34 ; futuro médio <span class=\"greek\">στήσομαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:15</a>. Passivo: 1º futuro <span class=\"greek\">σταθήσομαι</span> ; 1º aoristo <span class=\"greek\">ἐστάθην</span> (PEg 2 65). Ver <span class=\"greek\">στήκω</span> . Transitivo: A. Intransitivo: B, C, D .</p><p class=\"entry-text\">A. Uso transitivo (presente, imperfeito, futuro, 1º aoristo ativo ; ver B-D-F § 97, 1 ; Mlt-H. 241) geralmente «pôr, colocar, estabelecer».</p><p class=\"entry-text\">① fazer com que alguém esteja em determinado lugar ou posição; pôr, colocar, trazer, permitir que se apresente <span class=\"greek\">τινά</span>, alguém, literalmente <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">συνεδρίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:27</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτούς</span> diante deles 22:30. <span class=\"greek\">ἐκ</span> <span class=\"greek\">δεξιῶν</span> <span class=\"greek\">τινος</span> à direita de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:33</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> no meio, entre 18:2 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:36</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:3</a>. <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">τινος</span> diante de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:6</a>. Também <span class=\"greek\">κατενώπιόν</span> <span class=\"greek\">τινος</span> Jd 24. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> sobre alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:5</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:9</a>. <span class=\"greek\">παρά</span> <span class=\"greek\">τινι</span> ao lado de alguém 9:47.</p><p class=\"entry-text\">② apresentar alguém para assumir uma incumbência; propor, indicar, literalmente (por exemplo Just ., A I, 60, 3 <span class=\"greek\">Μωυσέα</span> … <span class=\"greek\">τύπον</span> <span class=\"greek\">σταυροῦ</span> … <span class=\"greek\">στῆσαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἁγίᾳ</span> <span class=\"greek\">σκηνῇ</span> ) <span class=\"greek\">τινά</span> para determinada finalidade: os candidatos à escolha para o apostolado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:23</a>. <span class=\"greek\">μάρτυρας</span> <span class=\"greek\">ψευδεῖς</span> 6:13 (cf. Mel. , P. 93, 700 <span class=\"greek\">ψευδομάρτυρες</span> ).</p><p class=\"entry-text\">③ instituir ou pôr em vigor; estabelecer, extensão figurada do sentido 1 (cf. Gen 26:3 <span class=\"greek\">τὸν</span> <span class=\"greek\">ὅρκον</span> ; Ex 6:4 ) <span class=\"greek\">τὴν</span> <span class=\"greek\">ἰδίαν</span> <span class=\"greek\">δικαιοσύνην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:3</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">δεύτερον</span> (em oposição a <span class=\"greek\">ἀναιρεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρῶτον</span>, referência ao sistema sacrificial) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:9</a>. —Quanto à aplicação jurídica <span class=\"greek\">κύριε</span>, <span class=\"greek\">μὴ</span> <span class=\"greek\">στήσῃς</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἁμαρτίαν</span> Senhor, não lhes imputes este pecado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.60\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:60</a> (em contraste com <span class=\"greek\">ἀφίημι</span> 1 Macc 13:38f ; 15:5 ; a expressão de Estêvão equivale a <span class=\"greek\">ἄφες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:34</a> ; ver Beginn. IV, ad loc. ).</p><p class=\"entry-text\">④ confirmar algo vigente ou praticado, reforçar sua validade; sustentar, manter, validar <span class=\"greek\">τὶ</span>, algo; extensão figurada do sentido 1 ( 1 Macc 2:27 <span class=\"greek\">τὴν</span> <span class=\"greek\">διαθήκην</span> ) <span class=\"greek\">τὴν</span> <span class=\"greek\">παράδοσιν</span> <span class=\"greek\">ὑμῶν</span> validar ou manter vossa própria tradição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:9</a>. <span class=\"greek\">νόμον</span> <span class=\"greek\">ἱστάνομεν</span> sustentamos a lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:31</a> (ver <span class=\"greek\">καταργέω</span> 2).</p><p class=\"entry-text\">⑤ tornar alguém firme, fazer alguém permanecer de pé <span class=\"greek\">δυνατεῖ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">στῆσαι</span> <span class=\"greek\">αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:4</a>.</p><p class=\"entry-text\">⑥ estipular contratualmente</p><p class=\"entry-text\">ⓐ estabelecer ou fixar uma data, um período de tempo <span class=\"greek\">ἡμέραν</span> (ver <span class=\"greek\">ἡμέρα</span> 3a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:31</a> .</p><p class=\"entry-text\">ⓑ determinar uma quantia em dinheiro <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἔστησαν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τριάκοντα</span> <span class=\"greek\">ἀργύρια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:15</a> (= Zech 11:12 <span class=\"greek\">ἔστησαν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μισθόν</span> <span class=\"greek\">μου</span> <span class=\"greek\">τριάκοντα</span> <span class=\"greek\">ἀργύρους</span> ), apresenta um problema especial aos intérpretes por causa dos interesses teológicos e narrativos do autor, que o levam a relacionar uma alusão a Zech 11:12 com uma declaração de cumprimento em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:9f</a>, a qual, à maneira da Hagadá, recorre a Zech 11:13 na forma mais longa de Mateus e a Jer 32 (Mt 39):7–9 (ver JDoeve, Jewish Hermeneutics in the Synoptic Gospels and Acts, ’54, 185–87). Jer 39:9 e Zech 11:12 empregam o verbo <span class=\"greek\">ἱ</span> . no sentido de pesar em balanças ( Hom .; X. , Cyr. 8, 2, 21, Mem. 1, 1, 9 al. ; GDI p. 870, n 49 A [Éfeso, séc. VI a.C.] 40 minas <span class=\"greek\">ἐστάθησαν</span> ; Is 46:6 ; Jer 39:9 ; 2 Esdr 8:25 ), e alguns intérpretes (por exemplo BWeiss, HHoltzmann, JWeiss; FSchulthess, ZNW 21, 1922, 227f; Field, Notes 19f) interpretam <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:15</a> nesse sentido. Naturalmente, os leitores de Mateus saberiam que as moedas de sua época não eram «pesadas» e compreenderiam <span class=\"greek\">ἱ</span> . no sentido de ajustar um acordo comercial ( <span class=\"greek\">ἵστημι</span> = fixar um preço, fazer uma oferta, concluir um acordo: Herodas 7, 68 par de sapatos; BGU 1116, 8 [I b.c. ]; 912, 25 [I a.d. ]; PRainer 206, 10 [II a.d. ] <span class=\"greek\">κεφάλαιον</span> ), eles lhe estabeleceram (= ofereceram, estipularam) 30 moedas de prata (= pagaram-lhe) ( Wlh. , OHoltzmann, Schniewind), mas os leitores mais instruídos entre eles reconheceriam prontamente o significado obsoleto. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.60\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:60</a> é por vezes interpretado num sentido relacionado, mas a ausência de objeto direto que indique quantia paga sugere que a passagem se enquadra melhor no sentido 3 acima.</p><p class=\"entry-text\">B. Uso intransitivo: formas do aoristo e do futuro</p><p class=\"entry-text\">① deixar de se mover e assumir posição estacionária; ficar parado, deter-se ( Hom ., Aristot .; Philostrat ., Ep. 36, 2 <span class=\"greek\">ὁ</span> <span class=\"greek\">ποταμὸς</span> <span class=\"greek\">στήσεται</span> ; TestSol 7:3 <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἔστη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">αὔρα</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:17</a>. <span class=\"greek\">στὰς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ἐφώνησεν</span> <span class=\"greek\">αὐτούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:32</a> .— <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:49</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:14</a> ; 17:12 ; 18:40. <span class=\"greek\">στῆναι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅρμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:38</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μακρόθεν</span> <span class=\"greek\">ἔστησαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:17</a> ; cf. no versículo 15. <span class=\"greek\">ἔστησαν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">τόπῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σπηλαίου</span> GJs 19:2. <span class=\"greek\">ἔστη</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τόπου</span> <span class=\"greek\">πεδινοῦ</span> ele se posicionou num lugar plano <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:17</a>. Referindo-se a uma estrela <span class=\"greek\">ἐστάθη</span> <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">παιδίον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:9</a> ; também <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παιδίου</span> GJs 21:3. Referindo-se ao término de um fluxo sanguíneo <span class=\"greek\">ἔστη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ῥύσις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἵματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:44</a> (cf. Ex 4:25 [embora HKosmala, Vetus Test. 12, ’62, 28 o traduza como um <span class=\"greek\">εἶναι</span> enfático ] Heraclid . Pont., Fgm. 49 W.; POxy 1088, 21 [I a.d. ]; Cyranides p. 117 note <span class=\"greek\">γυναικὶ</span> … <span class=\"greek\">αἷμα</span> <span class=\"greek\">ἵστημι</span> <span class=\"greek\">παραχρῆμα</span> ). <span class=\"greek\">στῆθι</span> fica de pé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:3</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">χεὶρ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἔστη</span> <span class=\"greek\">ἄνω</span> sua mão permaneceu erguida (imóvel) GJs 18:3 (não consta do papiro ).</p><p class=\"entry-text\">② apresentar-se na presença de outras pessoas; comparecer, pôr-se de pé, aparecer <span class=\"greek\">ἔμπροσθέν</span> <span class=\"greek\">τινος</span> diante de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:11</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:36</a>. Também <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:30</a> ; GJs 11:2 ( <span class=\"greek\">κατενώπιον</span> TestSol 22:13; Just ., D . 127, 3) ou <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span>: <span class=\"greek\">σταθήσεσθε</span> tereis de comparecer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:18</a> variante de leitura ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:9</a> ; <span class=\"greek\">ἐπί</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παλατίου</span> AcPl Ha 9, 20. <span class=\"greek\">στῆθι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέσον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:8</a> ; cf. versículo 8b ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:19</a>, 26 ( Vi. Aesopi I c. 6 p. 243, 15 <span class=\"greek\">Αἴσωπος</span> <span class=\"greek\">στὰς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">ἀνέκραξεν</span> ). Também <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:36</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:22</a> ; Ox 1 verso, 11 (ver Unknown Sayings , 69–71). <span class=\"greek\">ἔστη</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κριτήριον</span> ela compareceu perante o tribunal GJs 15:2. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:4</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:18</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:38</a>. Levantar-se ou postar-se para dizer algo ou proferir um discurso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:11</a>. Cf. 19:8 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:14</a> ; 5:20 ; 11:13 al. <span class=\"greek\">ἔστησαν</span> … <span class=\"greek\">προσδοκῶντες</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ζαχαρίαν</span> permaneceram à espera de Zacarias GJs 24:1. Praticamente no sentido do perfeito <span class=\"greek\">δυνάμενοι</span> … <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">στῆναι</span> (as imagens de culto) que não conseguiam permanecer de pé AcPl Ha 1, 20 (cf. <span class=\"greek\">ἵστατο</span> <span class=\"greek\">δένδρον</span> <span class=\"greek\">κυπάρισσος</span> TestAbr A 3 p. 79, 17 [Stone p. 6]; <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἱστάμεθα</span> GrBar 6:13 ).</p><p class=\"entry-text\">③ levantar-se contra, resistir; com <span class=\"greek\">πρὸς</span> e acusativo: oferecer resistência ( Thu . 5, 104) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:11</a> ; em emprego absoluto: resistir ( Ex 14:13 ) no versículo 13. (Compare-se o termo <span class=\"greek\">στάσις</span> no sentido de «rebelião».)</p><p class=\"entry-text\">④ manter-se firme para conservar a estabilidade; permanecer firme, não ceder terreno ( Ps 35:13 ) em batalha ( X. , An. 1, 10, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:14</a>. <span class=\"greek\">σταθήσεται</span> permanecerá firme <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:4a</a>. <span class=\"greek\">τίς</span> <span class=\"greek\">δύναται</span> <span class=\"greek\">σταθῆναι</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:17</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἣν</span> <span class=\"greek\">στῆτε</span> permanecer firmes nela ( Goodsp., Probs. 198) 1 Pt:12. Referindo-se a casa, cidade ou reino <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:25f</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:24f</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:18</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:26</a>. A expressão do Antigo Testamento ( Dt 19:15 ) <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">δύο</span> <span class=\"greek\">μαρτύρων</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τριῶν</span> <span class=\"greek\">σταθῇ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">ῥῆμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:16</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:1</a>.</p><p class=\"entry-text\">⑤ assumir a posição ereta, levantar-se <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> sobre os próprios pés ( Ezk 2:1 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:16</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:11</a>. Uso absoluto em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:8</a>.</p><p class=\"entry-text\">C. Uso intransitivo: perfeito e mais-que-perfeito</p><p class=\"entry-text\">① estar de pé, «estou em pé», «estava em pé»; referindo-se à posição corporal, por exemplo, de alguém que fala <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:37</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:25</a>, de ouvintes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:29</a> ou espectadores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:47</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:35</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:11</a>, de acusadores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:10</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:5</a>, 16, 18ab, 25 ; 19:25 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:9</a> al.</p><p class=\"entry-text\">② estar num lugar, estar (ali), encontrar-se (ali), com menor ênfase em «estar de pé» do que em «estar, existir».</p><p class=\"entry-text\">ⓐ posição indicada por advérbio de lugar <span class=\"greek\">ἔξω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:46f</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:20</a> ; 13:25. <span class=\"greek\">μακρόθεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:13</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μακρόθεν</span> a certa distância 23:49 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:10</a>. <span class=\"greek\">ἐκεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:5</a>. <span class=\"greek\">ὅπου</span> 13:14. <span class=\"greek\">ὧδε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:28</a> ; 20:6b. <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:27</a> ; <span class=\"greek\">ἀπέναντι</span> AcPl Ha 3, 30.</p><p class=\"entry-text\">ⓑ com o lugar indicado por uma preposição <span class=\"greek\">ἐκ</span> <span class=\"greek\">δεξιῶν</span> <span class=\"greek\">τινος</span> à direita de alguém ou de alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:11</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.55\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:55f</a> (HOwen, NTS 1, ’54/55, 224–26). <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτοῖς</span> entre eles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:21</a> ; com <span class=\"greek\">ἐν</span> e dativo de lugar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:3</a> ; 24:15 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.56\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:56</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:17</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:9</a> variante de leitura <span class=\"greek\">μέσος</span> <span class=\"greek\">ὑμῶν</span> 1:26 ( variante de leitura <span class=\"greek\">στήκει</span> ). <span class=\"greek\">ἐπί</span> com genitivo ( X. , Cyr. 3, 3, 66; Apollodorus [II b.c. ]: 244 Fgm. 209 Jac. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θύρας</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:23</a> ; 21:40 ; 24:20 ; 25:10 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:5</a>, 8 ; AcPl Ha 7, 37; com dativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:33</a> ; com acusativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:2</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:20</a> ; 7:1 ; 14:1 ; 15:2 ; GJs 5:2 ( <span class=\"greek\">ἕστηκας</span> códices, <span class=\"greek\">ἔστης</span> papiro ). <span class=\"greek\">παρά</span> com acusativo de lugar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:1f</a>. <span class=\"greek\">πέραν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:22</a>. <span class=\"greek\">πρό</span> com genitivo de lugar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:14</a>. <span class=\"greek\">πρός</span> com dativo de lugar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:11</a>. <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:14</a>. <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> AcPl Ha 11, 3. <span class=\"greek\">κύκλῳ</span> <span class=\"greek\">τινός</span> em redor de alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:11</a>. Com <span class=\"greek\">ἐνώπιον</span> (funcionando como preposição) <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:9</a> ; 11:4 ; 12:4 ; 20:12.</p><p class=\"entry-text\">ⓒ uso absoluto (Epict . 4, 1, 88 <span class=\"greek\">ἑστῶσα</span> da cidadela, simplesmente estando ali; Tat . 26, 2 <span class=\"greek\">παρατρέχοντας</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ὑμᾶς</span>, <span class=\"greek\">ἑστῶτα</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.73\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:73</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:35</a> ; 3:29 ; 20:14 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:25</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρόβατα</span> <span class=\"greek\">εἱστήκει</span> as ovelhas permaneceram imóveis GJs 18:2 (não consta do papiro). O verbo, isoladamente, no sentido de permanecer em pé sem fazer nada ( Eur ., Iph. Aul. 861; Aristoph ., Av. 206, Eccl. 852; Herodas 4, 44) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:6a</a>. <span class=\"greek\">ἀργός</span> pode ser acrescentado ( Aristoph ., Eccl. 879f, Pax 256 <span class=\"greek\">ἕστηκας</span> <span class=\"greek\">ἀργός</span> ) versículo 6a variante de leitura, 6b (quanto à pergunta cf. Eubulus Com. , Fgm. 15, 1 K. <span class=\"greek\">τί</span> <span class=\"greek\">ἕστηκας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πύλαις</span> ; Herodas 5, 40). Com palavras modificadoras ( Pla ., Phdr. 275d <span class=\"greek\">ἕστηκε</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ζῶντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔκγονα</span> ) <span class=\"greek\">εἱστήκεισαν</span> <span class=\"greek\">ἐνεοί</span> permaneceram ali sem fala <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:7</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐσφαγμένον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:6</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:6</a>. <span class=\"greek\">εἱστήκει</span> <span class=\"greek\">ἀπεκδεχόμενος</span> AcPl Ant 13, 22 (= Aa I, 237, 5).</p><p class=\"entry-text\">③ estar presente para servir a alguém; assistir, ser servo de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:2</a> (RCharles, Rv ICC vol. 1, p. 225 ).</p><p class=\"entry-text\">④ permanecer firme na fé; manter-se firme no compromisso pessoal em geral ( em oposição a <span class=\"greek\">πεσεῖν</span> ), extensão figurada do sentido 1, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:12</a> ; 2 Cl 2:6 . <span class=\"greek\">τ</span>. <span class=\"greek\">πίστει</span> <span class=\"greek\">ἕστηκας</span> permaneces firme por causa da tua fé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:20</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:24</a>. <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἕστηκεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">καρδίᾳ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἑδραῖος</span> aquele que permanece firme em seu coração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:37</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεμέλιος</span> <span class=\"greek\">ἕστηκεν</span> o fundamento permanece (inabalável) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:19</a> ( Stob . 4, 41, 60 [ vol. V, p. 945]: Apelles, ao ser perguntado por que representara Tique [Fortuna] sentada, respondeu <span class=\"greek\">οὐχ</span> <span class=\"greek\">ἕστηκεν</span> <span class=\"greek\">γάρ</span> =porque ela não consegue ficar de pé, isto é, carece de estabilidade; Hierocles 11, 441 <span class=\"greek\">ἑστῶτος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> =uma vez que a lei permanece firme [inalterada]; Procop. Soph ., Ep. 47 <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ἑστηκὸς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀκίνητον</span> ; 75).</p><p class=\"entry-text\">⑤ estar numa condição ou estado, permanecer ou encontrar-se em alguma coisa , extensão figurada do sentido 1; graça ( Hierocles 12, 446 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀρετῇ</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:2</a> ; no âmbito do evangelho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:1</a> ; na verdade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:44</a>.</p><p class=\"entry-text\">D. Uso intransitivo: presente médio, ter início, começar, expressão calendárica (atestado já em Homero) <span class=\"greek\">μὴν</span> <span class=\"greek\">ἱστάμενος</span> o mês que está começando ( frequente em inscrições ) MPol 21 — B. 835. DELG . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0177-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱστίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">vela de embarcação (assim, principalmente no plural , Hom . et al. ; também em inscrições e papiros ; Is 33:23 ; Just ., A I, 55, 3) <span class=\"greek\">συστέλλειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱ</span> . reduzir as velas ou recolhê-las completamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:15</a> variante de leitura — B. 736. DELG sob o verbete <span class=\"greek\">ἱστός</span> .</p></section></article>\n"};
